{* Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/parts/timeline.json
    A vertical list of events (an order's history): a dot on a line, the title, an optional text and the time. Newest first or oldest first is the caller's order.
    Props (p): items, className. *}
{var $k_TONE_DOT = ['gray' => 'bg-muted-foreground', 'green' => 'bg-emerald-500', 'blue' => 'bg-blue-500', 'amber' => 'bg-amber-500', 'red' => 'bg-red-500']}
{var $v_items = ($p['items'] ?? null)}
{capture $c_9}
  {capture $c_8}
    {foreach og_l($v_items) as $v_item}
      {var $v_i = $iterator->counter0}
      {capture $c_7}
        {capture $c_1}
          {if og_t(og_lt($v_i, og_sub(og_len($v_items), 1)))}
            {=og_include('compose/Inline.latte', ['class' => 'absolute top-4 -bottom-0 w-px bg-border'])|noescape}
          {/if}
          {=og_include('compose/Inline.latte', ['class' => og_s(og_cnv(['mt-2 size-2 rounded-full', og_at($k_TONE_DOT, og_coalesce([og_get($v_item, ['tone']), 'gray']))]))])|noescape}
        {/capture}
        {=og_include('compose/Box.latte', ['class' => 'relative flex w-2 shrink-0 justify-center', 'children' => (string) $c_1])|noescape}
        {capture $c_6}
          {capture $c_4}
            {capture $c_2}
              {=og_text(og_get($v_item, ['title']))}
            {/capture}
            {=og_include('compose/Text.latte', ['class' => 'm-0 text-sm font-bold text-foreground', 'children' => (string) $c_2])|noescape}
            {capture $c_3}
              {=og_text(og_get($v_item, ['time']))}
            {/capture}
            {=og_include('compose/Text.latte', ['class' => 'm-0 shrink-0 text-xs font-medium text-muted-foreground', 'children' => (string) $c_3])|noescape}
          {/capture}
          {=og_include('compose/Box.latte', ['class' => 'flex flex-wrap items-baseline justify-between gap-x-4', 'children' => (string) $c_4])|noescape}
          {if og_t(og_get($v_item, ['text']))}
            {capture $c_5}
              {=og_text(og_get($v_item, ['text']))}
            {/capture}
            {=og_include('compose/Text.latte', ['class' => 'm-0 text-xs font-medium text-muted-foreground', 'children' => (string) $c_5])|noescape}
          {/if}
        {/capture}
        {=og_include('compose/Box.latte', ['class' => 'flex min-w-0 flex-1 flex-col gap-0', 'children' => (string) $c_6])|noescape}
      {/capture}
      {=og_include('compose/ListItem.latte', ['class' => 'relative flex min-w-0 gap-4 pb-4 last:pb-0', 'attrs' => og_attrs(['data-event', og_get($v_item, ['id']), 'data-slot', 'timeline-item']), 'children' => (string) $c_7])|noescape}
    {/foreach}
  {/capture}
  {=og_include('compose/List.latte', ['class' => 'm-0 flex list-none flex-col p-0', 'children' => (string) $c_8])|noescape}
{/capture}
{=og_include('compose/Box.latte', ['class' => og_s(og_cnv(['min-w-0', ($p['className'] ?? '')])), 'attrs' => og_attrs(['data-slot', 'timeline']), 'children' => (string) $c_9])|noescape}
